---
// Theme toggle component with dark/light mode switching
---

<button
	id="theme-toggle"
	type="button"
	class="relative inline-flex items-center justify-center p-2 rounded-lg text-secondary-600 hover:text-primary-600 hover:bg-secondary-100 dark:text-secondary-400 dark:hover:text-primary-400 dark:hover:bg-secondary-800 transition-colors focus-ring"
	aria-label="Toggle dark mode"
>
	<!-- Sun icon for light mode -->
	<svg 
		id="sun-icon" 
		class="w-5 h-5 hidden" 
		fill="currentColor" 
		viewBox="0 0 20 20"
	>
		<path fill-rule="evenodd" d="M10 2a1 1 0 011 1v1a1 1 0 11-2 0V3a1 1 0 011-1zm4 8a4 4 0 11-8 0 4 4 0 018 0zm-.464 4.95l.707.707a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414zm2.12-10.607a1 1 0 010 1.414l-.706.707a1 1 0 11-1.414-1.414l.707-.707a1 1 0 011.414 0zM17 11a1 1 0 100-2h-1a1 1 0 100 2h1zm-7 4a1 1 0 011 1v1a1 1 0 11-2 0v-1a1 1 0 011-1zM5.05 6.464A1 1 0 106.465 5.05l-.708-.707a1 1 0 00-1.414 1.414l.707.707zm1.414 8.486l-.707.707a1 1 0 01-1.414-1.414l.707-.707a1 1 0 011.414 1.414zM4 11a1 1 0 100-2H3a1 1 0 000 2h1z" clip-rule="evenodd"/>
	</svg>

	<!-- Moon icon for dark mode -->
	<svg 
		id="moon-icon" 
		class="w-5 h-5" 
		fill="currentColor" 
		viewBox="0 0 20 20"
	>
		<path d="M17.293 13.293A8 8 0 016.707 2.707a8.001 8.001 0 1010.586 10.586z"/>
	</svg>
</button>

<script>
	// Theme toggle functionality
	const themeToggle = document.getElementById('theme-toggle');
	const sunIcon = document.getElementById('sun-icon');
	const moonIcon = document.getElementById('moon-icon');
	const html = document.documentElement;

	// Check for saved theme preference or default to light mode
	const currentTheme = localStorage.getItem('theme') || 'light';

	if (currentTheme === 'dark') {
		html.classList.add('dark');
		sunIcon.classList.remove('hidden');
		moonIcon.classList.add('hidden');
	} else {
		html.classList.remove('dark');
		sunIcon.classList.add('hidden');
		moonIcon.classList.remove('hidden');
	}

	// Toggle theme
	themeToggle?.addEventListener('click', () => {
		if (html.classList.contains('dark')) {
			html.classList.remove('dark');
			localStorage.setItem('theme', 'light');
			sunIcon.classList.add('hidden');
			moonIcon.classList.remove('hidden');
		} else {
			html.classList.add('dark');
			localStorage.setItem('theme', 'dark');
			sunIcon.classList.remove('hidden');
			moonIcon.classList.add('hidden');
		}
	});

	// Listen for system theme changes
	const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
	mediaQuery.addEventListener('change', (e) => {
		if (!localStorage.getItem('theme')) {
			if (e.matches) {
				html.classList.add('dark');
				sunIcon.classList.remove('hidden');
				moonIcon.classList.add('hidden');
			} else {
				html.classList.remove('dark');
				sunIcon.classList.add('hidden');
				moonIcon.classList.remove('hidden');
			}
		}
	});
</script>
